"""The migrations match the models and can be rolled all the way back and re-applied."""

import asyncio
from decimal import Decimal
from typing import Any

from alembic import command
from sqlalchemy import NullPool, text
from sqlalchemy.ext.asyncio import create_async_engine

from tests.conftest import TEST_DATABASE_URL, alembic_config


def test_models_match_migrations() -> None:
    # Raises AutogenerateDiffsDetected if a model change has no migration.
    command.check(alembic_config())


def test_downgrade_to_base_and_upgrade_again() -> None:
    config = alembic_config()
    command.downgrade(config, "base")
    command.upgrade(config, "head")


# ---------------------------------------------------------------- prod log fields backfill

BEFORE_LOG_FIELDS = "d4073174fb41"
LOG_FIELDS = "fc20ba24a501"


def _sql(statements: list[str], fetch: str | None = None) -> list[Any]:
    """Run statements in one committed transaction; optionally return rows of `fetch`."""

    async def run() -> list[Any]:
        engine = create_async_engine(TEST_DATABASE_URL, poolclass=NullPool)
        try:
            async with engine.begin() as conn:
                for statement in statements:
                    await conn.execute(text(statement))
                return list((await conn.execute(text(fetch))).all()) if fetch else []
        finally:
            await engine.dispose()

    return asyncio.run(run())


def test_log_fields_backfill_and_downgrade() -> None:
    config = alembic_config()
    command.downgrade(config, BEFORE_LOG_FIELDS)
    try:
        _sql(
            [
                "INSERT INTO users (username, email, password_hash, role) "
                "VALUES ('backfill_user', 'backfill@example.com', '!x', 'admin')",
                "INSERT INTO categories (label) VALUES ('Backfill category')",
                "INSERT INTO prod_logs (user_id, log_date, title, category_id, hours_spent, "
                "updated_by) SELECT u.id, '2026-11-02', 'Old row', c.id, 2.5, u.id "
                "FROM users u, categories c "
                "WHERE u.username = 'backfill_user' AND c.label = 'Backfill category'",
            ]
        )
        command.upgrade(config, LOG_FIELDS)

        rows = _sql(
            [],
            "SELECT a.label, w.is_default, l.is_planned, l.planned_hours, l.hours_spent "
            "FROM prod_logs l JOIN activities a ON a.id = l.activity_id "
            "JOIN work_setups w ON w.id = l.work_setup_id WHERE l.title = 'Old row'",
        )
        assert [tuple(r) for r in rows] == [("General", True, False, None, Decimal("2.50"))]

        # A planned-only row without a title survives a downgrade.
        _sql(
            [
                "INSERT INTO prod_logs (user_id, log_date, category_id, activity_id, "
                "work_setup_id, planned_hours, is_planned, updated_by) "
                "SELECT user_id, log_date, category_id, activity_id, work_setup_id, 4, true, "
                "user_id FROM prod_logs WHERE title = 'Old row'"
            ]
        )
        command.downgrade(config, BEFORE_LOG_FIELDS)
        rows = _sql(
            [],
            "SELECT title, hours_spent FROM prod_logs l JOIN users u ON u.id = l.user_id "
            "WHERE u.username = 'backfill_user' ORDER BY l.id",
        )
        assert [tuple(r) for r in rows] == [
            ("Old row", Decimal("2.50")),
            ("General", Decimal("4.00")),
        ]
    finally:
        command.upgrade(config, "head")
        _sql(
            [
                "DELETE FROM prod_logs WHERE user_id IN "
                "(SELECT id FROM users WHERE username = 'backfill_user')",
                "DELETE FROM users WHERE username = 'backfill_user'",
                "DELETE FROM categories WHERE label = 'Backfill category'",
                "DELETE FROM activities WHERE label = 'General'",
            ]
        )


# ---------------------------------------------------------------- deviation reasons

BEFORE_DEVIATION_REASONS = "8f4facd661a4"


def test_deviation_reasons_conversion_and_downgrade() -> None:
    config = alembic_config()
    command.downgrade(config, BEFORE_DEVIATION_REASONS)
    try:
        insert_row = (
            "INSERT INTO prod_logs (user_id, log_date, category_id, activity_id, work_setup_id, "
            "hours_spent, description, deviation_reason, updated_by) "
            "SELECT u.id, '2026-11-02', c.id, a.id, w.id, 1, {description}, {reason}, u.id "
            "FROM users u, categories c, activities a, work_setups w "
            "WHERE u.username = 'reason_user' AND c.label = 'Reason category' "
            "AND a.label = 'Reason activity' AND w.is_default"
        )
        _sql(
            [
                "INSERT INTO users (username, email, password_hash, role) "
                "VALUES ('reason_user', 'reason@example.com', '!x', 'admin')",
                "INSERT INTO categories (label) VALUES ('Reason category')",
                "INSERT INTO activities (label) VALUES ('Reason activity')",
                insert_row.format(description="NULL", reason="' scope creep '"),
                insert_row.format(description="'Note'", reason="'Extra fixes'"),
            ]
        )
        command.upgrade(config, "head")

        fetch = (
            "SELECT d.label, l.description FROM prod_logs l "
            "JOIN users u ON u.id = l.user_id "
            "LEFT JOIN deviation_reasons d ON d.id = l.deviation_reason_id "
            "WHERE u.username = 'reason_user' ORDER BY l.id"
        )
        assert [tuple(r) for r in _sql([], fetch)] == [
            ("Scope Creep", None),
            (None, "Note\nReason for deviation: Extra fixes"),
        ]
        default = "SELECT label FROM work_setups WHERE is_default"
        assert [r[0] for r in _sql([], default)] == ["On-Site"]
        reasons = _sql([], "SELECT count(*) FROM deviation_reasons WHERE is_active")
        assert reasons[0][0] == 11

        command.downgrade(config, BEFORE_DEVIATION_REASONS)
        rows = _sql(
            [],
            "SELECT deviation_reason FROM prod_logs l JOIN users u ON u.id = l.user_id "
            "WHERE u.username = 'reason_user' ORDER BY l.id",
        )
        assert [r[0] for r in rows] == ["Scope Creep", None]
        assert [r[0] for r in _sql([], default)] == ["Remote"]
    finally:
        command.upgrade(config, "head")
        _sql(
            [
                "DELETE FROM prod_logs WHERE user_id IN "
                "(SELECT id FROM users WHERE username = 'reason_user')",
                "DELETE FROM users WHERE username = 'reason_user'",
                "DELETE FROM categories WHERE label = 'Reason category'",
                "DELETE FROM activities WHERE label = 'Reason activity'",
            ]
        )


# ---------------------------------------------------------------- log title and task link

BEFORE_DROP_TITLE = "1ab76ae928ea"


def test_log_title_moves_into_remarks() -> None:
    config = alembic_config()
    command.downgrade(config, BEFORE_DROP_TITLE)
    try:
        insert_row = (
            "INSERT INTO prod_logs (user_id, log_date, category_id, activity_id, work_setup_id, "
            "hours_spent, title, description, updated_by) "
            "SELECT u.id, '2026-11-02', c.id, a.id, w.id, 1, {title}, {description}, u.id "
            "FROM users u, categories c, activities a, work_setups w "
            "WHERE u.username = 'title_user' AND c.label = 'Title category' "
            "AND a.label = 'Title activity' AND w.is_default"
        )
        _sql(
            [
                "INSERT INTO users (username, email, password_hash, role) "
                "VALUES ('title_user', 'title@example.com', '!x', 'admin')",
                "INSERT INTO categories (label) VALUES ('Title category')",
                "INSERT INTO activities (label) VALUES ('Title activity')",
                insert_row.format(title="'UAT'", description="'With the client'"),
                insert_row.format(title="'Only a note'", description="NULL"),
                insert_row.format(title="NULL", description="'Only remarks'"),
            ]
        )
        command.upgrade(config, "head")

        rows = _sql(
            [],
            "SELECT description FROM prod_logs l JOIN users u ON u.id = l.user_id "
            "WHERE u.username = 'title_user' ORDER BY l.id",
        )
        assert [r[0] for r in rows] == ["UAT - With the client", "Only a note", "Only remarks"]
    finally:
        command.upgrade(config, "head")
        _sql(
            [
                "DELETE FROM prod_logs WHERE user_id IN "
                "(SELECT id FROM users WHERE username = 'title_user')",
                "DELETE FROM users WHERE username = 'title_user'",
                "DELETE FROM categories WHERE label = 'Title category'",
                "DELETE FROM activities WHERE label = 'Title activity'",
            ]
        )
